import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"命令与权限","description":"","frontmatter":{},"headers":[],"relativePath":"modules/kits/commands.md","filePath":"modules/kits/commands.md","lastUpdated":0}`),a={name:`modules/kits/commands.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to “命令与权限”">​</a></h1><p>EmakiKits 的主命令是 <code>/emakikits</code>, 别名 <code>/emakikit</code> 与 <code>/ekits</code>. 所有子命令先检查 <code>emakikits.use</code>, 再按子命令检查对应权限</p><h2 id="玩家命令" tabindex="-1">玩家命令 <a class="header-anchor" href="#玩家命令" aria-label="Permalink to “玩家命令”">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>权限</th></tr></thead><tbody><tr><td><code>/emakikits help</code></td><td>显示可用子命令</td><td><code>emakikits.use</code></td></tr><tr><td><code>/emakikits list</code></td><td>列出已加载礼包 (类型, id, 显示名, 是否启用)</td><td><code>emakikits.use</code></td></tr><tr><td><code>/emakikits claim &lt;礼包ID&gt;</code></td><td>领取礼包</td><td><code>emakikits.claim</code></td></tr><tr><td><code>/emakikits choose &lt;礼包ID&gt; [选项...]</code></td><td>不带选项打开自选 GUI; 带选项 id 直接提交选择</td><td><code>emakikits.open</code></td></tr><tr><td><code>/emakikits buy &lt;礼包ID&gt;</code></td><td>购买一次可领取次数 (经 CoreLib 经济桥扣费)</td><td><code>emakikits.buy</code></td></tr><tr><td><code>/emakikits redeem &lt;礼包ID&gt; &lt;兑换码&gt;</code></td><td>兑换 CDK 礼包</td><td><code>emakikits.redeem</code></td></tr><tr><td><code>/emakikits invite &lt;玩家名&gt;</code></td><td>绑定邀新关系 (被邀请人需在线)</td><td><code>emakikits.invite</code></td></tr><tr><td><code>/emakikits open &lt;礼包ID&gt;</code></td><td>领取礼包, 与 <code>claim</code> 等价</td><td><code>emakikits.open</code></td></tr></tbody></table><h2 id="管理命令" tabindex="-1">管理命令 <a class="header-anchor" href="#管理命令" aria-label="Permalink to “管理命令”">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>权限</th></tr></thead><tbody><tr><td><code>/emakikits inspect &lt;玩家名&gt;</code></td><td>查看该玩家的审计记录条数与明细</td><td><code>emakikits.inspect</code></td></tr><tr><td><code>/emakikits grant &lt;玩家名&gt; &lt;礼包ID&gt;</code></td><td>给玩家增加一次可领取次数</td><td><code>emakikits.grant</code></td></tr><tr><td><code>/emakikits cdk list</code></td><td>列出 CDK 礼包及其兑换码数量</td><td><code>emakikits.cdk</code></td></tr><tr><td><code>/emakikits cdk disable &lt;兑换码&gt;</code></td><td>停用兑换码</td><td><code>emakikits.cdk</code></td></tr><tr><td><code>/emakikits reload</code></td><td>重新加载 <code>config.yml</code>, <code>kits/*.yml</code>, lang 与 GUI 模板, 并重注册 cron 窗口</td><td><code>emakikits.reload</code></td></tr></tbody></table><h2 id="权限表" tabindex="-1">权限表 <a class="header-anchor" href="#权限表" aria-label="Permalink to “权限表”">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>emakikits.use</code></td><td><code>true</code></td><td>使用玩家命令的根权限</td></tr><tr><td><code>emakikits.claim</code></td><td><code>true</code></td><td>领取礼包</td></tr><tr><td><code>emakikits.open</code></td><td><code>true</code></td><td>打开自选 GUI / 领取已购买礼包</td></tr><tr><td><code>emakikits.buy</code></td><td><code>true</code></td><td>购买礼包</td></tr><tr><td><code>emakikits.redeem</code></td><td><code>true</code></td><td>兑换 CDK</td></tr><tr><td><code>emakikits.invite</code></td><td><code>true</code></td><td>绑定邀新关系</td></tr><tr><td><code>emakikits.admin</code></td><td><code>op</code></td><td>管理权限父节点, 含下列子权限</td></tr><tr><td><code>emakikits.reload</code> / <code>grant</code> / <code>inspect</code> / <code>cdk</code></td><td><code>op</code></td><td>分别对应重载, 发放, 审计, CDK 管理</td></tr></tbody></table><h2 id="tab-补全" tabindex="-1">Tab 补全 <a class="header-anchor" href="#tab-补全" aria-label="Permalink to “Tab 补全”">​</a></h2><p>一级子命令 (<code>help</code>, <code>list</code>, <code>claim</code>, <code>choose</code>, <code>buy</code>, <code>redeem</code>, <code>invite</code>, <code>open</code>, <code>inspect</code>, <code>grant</code>, <code>cdk</code>, <code>reload</code>) 与需要礼包 id 的子命令第二参数 (来自 <code>kits/*.yml</code> 的 id 集合) 提供补全</p><h2 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to “说明”">​</a></h2><ul><li>CDK 礼包不能通过 <code>claim</code> 领取, 必须用 <code>redeem</code>; 邀新礼包通过入服邀请码流程绑定, 不走 <code>claim</code></li><li><code>choose</code> 带选项 id 时按 <code>min_select</code> / <code>max_select</code> 校验数量, 权限与未配置选项, 然后发放该选项小礼包内的全部奖励</li><li>领取, 兑换与购买失败时返回对应语言键 (如 <code>error.kit.already_claimed</code>, <code>error.cdk.exhausted</code>), 不会静默吞掉</li></ul>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};